<?php
/** Eight-component frozen monthly submissions. Financial values are never editable here. */
require_once __DIR__.'/budget_actuals.php';require_once __DIR__.'/accounting_periods.php';require_once __DIR__.'/report_bundle_storage.php';
const REPORT_BUNDLE_COMPONENTS=['worksheet','trial_balance','income_statement','financial_position','cash_flows','project_activity','advance_aging','budget_actuals'];
/** Financial-source comparison excludes display-only component byte hashes.
 * The full immutable payload/hash and each component/hash still protect all frozen bytes. */
function report_bundle_source_fingerprint(array $manifest):string{$source=$manifest;unset($source['component_hashes']);return hash('sha256',reporting_json($source));}
function report_bundle_require(PDO $pdo):void{budget_revision_require($pdo);periods_require($pdo);}
function report_bundle_model(PDO $pdo,int $uid,string $month):array
{
    return accounting_read($pdo,function()use($pdo,$uid,$month){reporting_actor($pdo,$uid);report_bundle_require($pdo);$month=reporting_month($month);$financial=financial_report_model($pdo,$uid,$month);$budget=budget_actual_model($pdo,$uid,$month);$period=periods_root($pdo,$month);$components=['worksheet'=>['rows'=>$financial['worksheet'],'totals'=>$financial['worksheet_totals'],'derived_results'=>$financial['worksheet_derived_results']],'trial_balance'=>$financial['trial_balance'],'income_statement'=>$financial['income_statement'],'financial_position'=>$financial['financial_position'],'cash_flows'=>$financial['cash_flows'],'project_activity'=>$financial['project_activity'],'advance_aging'=>$financial['advance_aging'],'budget_actuals'=>$budget];$hashes=[];foreach($components as $name=>$component)$hashes[$name]=hash('sha256',reporting_json($component));
        $s=$pdo->prepare("SELECT j.id,j.entry_date,j.reference,j.description,j.source_book,j.transaction_kind,l.id line_id,l.account_id,l.debit_amount,l.credit_amount,l.fund_project_id,l.project_code_snapshot,l.project_name_snapshot FROM journal_entries j JOIN journal_entry_lines l ON l.journal_entry_id=j.id WHERE j.status='posted' AND j.entry_date<=? ORDER BY j.entry_date,j.id,l.id");$s->execute([$financial['as_of']]);$sourceLines=$s->fetchAll(PDO::FETCH_ASSOC);
        $s=$pdo->prepare('SELECT id,target_journal_id,reversal_journal_id,replacement_journal_id,accounting_date,request_hash FROM journal_corrections WHERE accounting_date<=? ORDER BY id');$s->execute([$financial['as_of']]);$corrections=$s->fetchAll(PDO::FETCH_ASSOC);
        $s=$pdo->prepare('SELECT e.id,e.advance_id,e.old_due_date,e.new_due_date,e.effective_date,e.created_by,e.created_at FROM cash_advance_due_changes e JOIN cash_advances a ON a.id=e.advance_id JOIN journal_entries j ON j.id=a.release_journal_id WHERE e.effective_date<=? AND j.entry_date<=? ORDER BY e.effective_date,e.id');$s->execute([$financial['as_of'],$financial['as_of']]);$deadlines=$s->fetchAll(PDO::FETCH_ASSOC);
        $configuration=$financial['configuration']?report_configuration_current($pdo,$financial['from']):null;$config=$configuration?['id'=>(int)$configuration['id'],'revision'=>(int)$configuration['revision_number'],'payload_hash'=>$configuration['payload_hash'],'payload'=>$configuration['payload']]:null;
        $manifest=['calculation_version'=>'complete_reports_v1','organization'=>'Atikha Finance','currency'=>'PHP','month'=>$month,'from'=>$financial['from'],'as_of'=>$financial['as_of'],'reporting_year_start_month'=>$financial['configuration']['year_start_month']??1,'source_lines'=>$sourceLines,'corrections'=>$corrections,'cutoff_due_changes'=>$deadlines,'configuration'=>$config,'budget_state'=>$budget['approval_state'],'approved_budget'=>$budget['approved']?['id'=>$budget['approved']['id'],'payload_hash'=>$budget['approved']['payload_hash'],'revision'=>$budget['approved']['revision'],'review'=>$budget['approved']['review']]:null,'component_hashes'=>$hashes,'financial_source'=>$financial['fingerprint'],'budget_source'=>$budget['fingerprint']];$fingerprint=report_bundle_source_fingerprint($manifest);$issues=array_values(array_unique(array_merge($financial['issues'],$budget['reporting_issues'])));$complete=$financial['core_complete']&&$financial['source_valid']&&$budget['complete'];
        return ['month'=>$month,'from'=>$financial['from'],'as_of'=>$financial['as_of'],'complete'=>$complete,'issues'=>$issues,'missing_approved_budget'=>$budget['approved']===null,'fingerprint'=>$fingerprint,'components'=>$components,'manifest'=>$manifest,'period'=>['state'=>$period['state'],'epoch'=>(int)$period['epoch']]];
    });
}
function report_bundle_identity($value,string $label):string{$v=reporting_text($value??'',64,$label,true);if(!preg_match('/\A[a-f0-9]{64}\z/',$v))throw new ReportingProblem('Reload the complete reports before confirming.',400);return $v;}
function report_bundle_epoch($value):int{if(is_int($value)&&$value>=0&&$value<=4294967295)return $value;if(is_string($value)&&preg_match('/\A(?:0|[1-9][0-9]{0,9})\z/',$value)&&(int)$value<=4294967295)return (int)$value;throw new ReportingProblem('Reload the current month state before confirming.',400);}
function report_bundle_submit(PDO $pdo,int $uid,array $r):array
{
    reporting_csrf($r);$month=reporting_month($r['month']??'');$key=report_bundle_identity($r['request_key']??null,'submission identity');$source=report_bundle_identity($r['source_fingerprint']??null,'report source');$epoch=report_bundle_epoch($r['expected_epoch']??null);$ack=($r['acknowledge_no_budget']??false)===true;$requestHash=hash('sha256',reporting_json([$month,$source,$epoch,$ack]));report_bundle_require($pdo);
    $out=reporting_tx($pdo,$uid,['Admin'],function($actor)use($pdo,$uid,$month,$key,$source,$epoch,$ack,$requestHash){report_bundle_require($pdo);$s=$pdo->prepare('SELECT id,request_hash FROM complete_report_bundles WHERE prepared_by=? AND request_key=?');$s->execute([$uid,$key]);if($old=$s->fetch(PDO::FETCH_ASSOC)){if(!hash_equals($old['request_hash'],$requestHash))throw new ReportingProblem('That submission identity was used with different reports.',409);report_bundle_load($pdo,$uid,(int)$old['id'],false);return ['id'=>(int)$old['id'],'duplicate'=>true];}
        $period=periods_root($pdo,$month,true,true);if($period['state']!=='Open'||(int)$period['epoch']!==$epoch)throw new ReportingProblem('The month state changed. Reload the reports before submitting.',409);$pdo->prepare('INSERT INTO complete_report_roots(report_month) VALUES(?) ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id)')->execute([$month.'-01']);$s=$pdo->prepare('SELECT * FROM complete_report_roots WHERE report_month=? FOR UPDATE');$s->execute([$month.'-01']);$root=$s->fetch(PDO::FETCH_ASSOC);$model=report_bundle_model($pdo,$uid,$month);if(!$model['complete'])throw new ReportingProblem('Complete the report setup and resolve the listed accounting issues before submitting all reports.',422);if(!hash_equals($source,$model['fingerprint']))throw new ReportingProblem('The reports changed. Reload and check them before submitting.',409);if($model['missing_approved_budget']&&!$ack)throw new ReportingProblem('Acknowledge that this month has no approved budget, or arrange budget approval before submitting.',422);
        $payload=['complete'=>true,'missing_approved_budget_acknowledged'=>$model['missing_approved_budget']&&$ack,'manifest'=>$model['manifest'],'components'=>$model['components']];$json=report_bundle_storage_encode($payload,(int)$pdo->query('SELECT @@max_allowed_packet')->fetchColumn());$s=$pdo->prepare('INSERT INTO complete_report_bundles(root_id,revision_number,period_epoch,prepared_by,prepared_at,prepared_name,request_key,request_hash,source_fingerprint,payload_hash,payload) VALUES(?,?,?,?,UTC_TIMESTAMP(),?,?,?,?,?,?)');$s->execute([$root['id'],$root['next_revision'],$epoch,$uid,$actor['FullName'],$key,$requestHash,$source,hash('sha256',$json),$json]);$id=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE complete_report_roots SET next_revision=next_revision+1 WHERE id=?')->execute([$root['id']]);reporting_audit($pdo,$uid,AUDIT_ACTION_REVIEW_REQUEST,'Complete monthly reports',$id,null,['month'=>$month,'revision'=>(int)$root['next_revision'],'source_fingerprint'=>$source,'components'=>REPORT_BUNDLE_COMPONENTS]);return ['id'=>$id,'duplicate'=>false];
    });$out['warning']='';if(!$out['duplicate']&&!notification_notify_management($pdo,'Complete monthly reports submitted for '.$month.'.','report_bundles.php?bundle_id='.$out['id']))$out['warning']='Complete reports saved, but their notification could not be delivered. They remain in the review queue.';return $out;
}
/** Direct entry points authenticate here; stored bytes never use current master labels. */
function report_bundle_load(PDO $pdo,int $uid,int $id,bool $compare=true):array
{
    return accounting_read($pdo,function()use($pdo,$uid,$id,$compare){reporting_actor($pdo,$uid);report_bundle_require($pdo);$s=$pdo->prepare('SELECT b.*,r.report_month FROM complete_report_bundles b JOIN complete_report_roots r ON r.id=b.root_id WHERE b.id=?');$s->execute([$id]);$row=$s->fetch(PDO::FETCH_ASSOC);if(!$row)throw new ReportingProblem('That complete report revision was not found.',404);$payload=report_bundle_storage_decode($row['payload'],$row['payload_hash']);if(($payload['complete']??false)!==true||!isset($payload['components'],$payload['manifest']))throw new ReportingProblem('The frozen complete reports need an integrity review.',503);$names=array_keys($payload['components']);$expected=REPORT_BUNDLE_COMPONENTS;sort($names);sort($expected);if($names!==$expected)throw new ReportingProblem('A frozen report component is missing or unexpected.',503);foreach($payload['components'] as $name=>$component)if(!hash_equals($payload['manifest']['component_hashes'][$name]??'',hash('sha256',reporting_json($component))))throw new ReportingProblem('A frozen report component needs an integrity review.',503);if(!hash_equals($row['source_fingerprint'],report_bundle_source_fingerprint($payload['manifest']))||($payload['manifest']['month']??null).'-01'!==$row['report_month'])throw new ReportingProblem('The frozen report source identity needs an integrity review.',503);
        $s=$pdo->prepare('SELECT id,decision,reason,actor_name,reviewed_at FROM complete_report_reviews WHERE bundle_id=?');$s->execute([$id]);$review=$s->fetch(PDO::FETCH_ASSOC)?:null;$month=substr($row['report_month'],0,7);$live=$compare?report_bundle_model($pdo,$uid,$month):null;return ['id'=>$id,'month'=>$month,'revision'=>(int)$row['revision_number'],'period_epoch'=>(int)$row['period_epoch'],'prepared_by'=>$row['prepared_name'],'prepared_at'=>$row['prepared_at'],'payload_hash'=>$row['payload_hash'],'source_fingerprint'=>$row['source_fingerprint'],'payload'=>$payload,'state'=>$review['decision']??'Requested','review'=>$review,'stale'=>$compare?!hash_equals($row['source_fingerprint'],$live['fingerprint']):null,'current_complete'=>$live['complete']??null];
    });
}
function report_bundle_review(PDO $pdo,int $uid,array $r):array
{
    reporting_csrf($r);$id=reporting_id($r['bundle_id']??null,'complete report revision');$key=report_bundle_identity($r['request_key']??null,'review identity');$hash=report_bundle_identity($r['payload_hash']??null,'frozen report identity');$decision=reporting_text($r['decision']??'',16,'decision',true);if(!in_array($decision,['Reviewed','Returned'],true))throw new ReportingProblem('Choose Mark reviewed or Return.',400);$reason=reporting_text($r['reason']??'',2000,'review reason',$decision==='Returned');$requestHash=hash('sha256',reporting_json([$id,$hash,$decision,$reason]));report_bundle_require($pdo);
    $out=reporting_tx($pdo,$uid,['Management'],function($actor)use($pdo,$uid,$id,$key,$hash,$decision,$reason,$requestHash){report_bundle_require($pdo);$s=$pdo->prepare('SELECT id,bundle_id,request_hash FROM complete_report_reviews WHERE actor_id=? AND request_key=?');$s->execute([$uid,$key]);if($old=$s->fetch(PDO::FETCH_ASSOC)){if((int)$old['bundle_id']!==$id||!hash_equals($old['request_hash'],$requestHash))throw new ReportingProblem('That review identity was used for another decision.',409);return ['id'=>$id,'review_id'=>(int)$old['id'],'duplicate'=>true];}
        $peek=report_bundle_load($pdo,$uid,$id,false);$period=periods_root($pdo,$peek['month'],true);$s=$pdo->prepare('SELECT id FROM complete_report_bundles WHERE id=? FOR UPDATE');$s->execute([$id]);$frozen=report_bundle_load($pdo,$uid,$id,false);if(!hash_equals($frozen['payload_hash'],$hash))throw new ReportingProblem('Review this exact frozen revision before deciding.',409);if($frozen['state']!=='Requested')throw new ReportingProblem('This complete revision already has a recorded decision.',409);if($decision==='Reviewed'){$live=report_bundle_model($pdo,$uid,$frozen['month']);if(!$live['complete']||!hash_equals($frozen['source_fingerprint'],$live['fingerprint'])||(int)$period['epoch']!==$frozen['period_epoch'])throw new ReportingProblem('These reports are stale. Return this revision and ask the Admin to submit current complete reports.',409);}
        $s=$pdo->prepare('INSERT INTO complete_report_reviews(bundle_id,decision,reason,actor_id,actor_name,reviewed_at,request_key,request_hash) VALUES(?,?,?,?,?,UTC_TIMESTAMP(),?,?)');$s->execute([$id,$decision,$reason,$uid,$actor['FullName'],$key,$requestHash]);$review=(int)$pdo->lastInsertId();reporting_audit($pdo,$uid,AUDIT_ACTION_REVIEW_COMPLETE,'Complete monthly reports',$id,['state'=>'Requested'],['state'=>$decision,'reason'=>$reason,'payload_hash'=>$hash]);return ['id'=>$id,'review_id'=>$review,'duplicate'=>false];
    });$out['warning']='';if(!$out['duplicate']){$s=$pdo->prepare('SELECT prepared_by FROM complete_report_bundles WHERE id=?');$s->execute([$id]);if(!notification_create($pdo,(int)$s->fetchColumn(),null,'Your complete monthly reports were '.strtolower($decision).'.','report_bundles.php?bundle_id='.$id))$out['warning']='Review saved, but its notification could not be delivered.';}return $out;
}
function report_bundle_queue(PDO $pdo,int $uid,string $filter='pending',int $limit=100):array
{
    return accounting_read($pdo,function()use($pdo,$uid,$filter,$limit){reporting_actor($pdo,$uid);$schema=periods_schema($pdo);if($schema['state']==='absent')return [];if(!$schema['complete'])throw new ReportingProblem('Complete report review is unavailable until deployment is complete.',503);if(!in_array($filter,['pending','all'],true)||$limit<1||$limit>100)throw new LogicException('Invalid complete report queue scope.');return $pdo->query("SELECT b.id,r.report_month,b.revision_number,b.prepared_name,b.prepared_at,COALESCE(v.decision,'Requested') state FROM complete_report_bundles b JOIN complete_report_roots r ON r.id=b.root_id LEFT JOIN complete_report_reviews v ON v.bundle_id=b.id ".($filter==='pending'?'WHERE v.id IS NULL ':'').'ORDER BY r.report_month DESC,b.revision_number DESC LIMIT '.$limit)->fetchAll(PDO::FETCH_ASSOC);});
}
